mapper.sql:
FROM encyclopedia_breed b
JOIN encyclopedia_category c ON c.id=b.category_id

    AND b.status=#{status}
    AND b.category_id=#{categoryId}
    AND (LOWER(b.name) LIKE #{keywordPattern} OR LOWER(b.aliases) LIKE #{keywordPattern})

mapper.update:
UPDATE encyclopedia_category
SET category_name = COALESCE(#{categoryName}, category_name),
    sort_no       = COALESCE(#{sortNo}, sort_no),
    status        = COALESCE(#{status}, status),
    version       = version + 1,
    updated_at    = #{now}
WHERE category_code=#{categoryCode} AND version=#{expectedVersion}
AND status=#{fromStatus}

UPDATE encyclopedia_breed
SET summary=#{summary}, cover_url=#{coverUrl}, body_type=#{bodyType},
    aliases=#{aliases}, tags=#{tags}, sort_no=#{sortNo},
    version=version + 1, updated_at=#{now}
WHERE id=#{breedId} AND version=#{expectedVersion}

UPDATE encyclopedia_breed
SET status=#{toStatus}, version=version + 1, updated_at=#{now}
WHERE id=#{breedId} AND status=#{fromStatus} AND version=#{expectedVersion}
